INSERT INTO merchant_qa (qa_id, merchant_id, user_id, question, answer, answered_by, created_at) VALUES ('QA_RIVER_WHEELCHAIR', 'M_RIVER_HOTEL', 'u_ella', 'Does the ballroom route remain step-free after the portable stage is installed?', 'The lobby route is step-free, but the stage reduces the clear turning area near the east doors. Facilities recommends the west-side seating plan.', 'River Hotel Events', '2026-06-04T10:20:00Z');
INSERT INTO merchant_qa (qa_id, merchant_id, user_id, question, answer, answered_by, created_at) VALUES ('QA_LIBRARY_AUDIO', 'M_LIBRARY_HALL', 'u_ella', 'Can the hall support two wireless microphones for a moderated discussion?', 'The venue supplies one wired microphone. A second wireless unit must be brought by the organizer, and amplified music ends at 20:30.', 'Library Garden Desk', '2026-06-17T08:40:00Z');
INSERT INTO merchant_qa (qa_id, merchant_id, user_id, question, answer, answered_by, created_at) VALUES ('QA_SKY_INVOICE', 'M_SKY_ROOM', 'u_ella', 'Can the reading room issue a corporate invoice for an evening workshop?', 'A corporate invoice is available for the room fee. Catering is billed by the building cafe under a separate invoice.', 'Skyline Reading Room', '2026-07-01T09:15:00Z');
INSERT INTO merchant_qa (qa_id, merchant_id, user_id, question, answer, answered_by, created_at) VALUES ('QA_CEDAR_JULY_CLOSE', 'M_CEDAR_TABLE', 'u_ella', 'Were the July special meals served with separate utensils?', 'Yes. The service log records sealed portions, color-coded tongs, and a named banquet captain for the full meal period.', 'Cedar Table Manager', '2026-07-23T07:50:00Z');
INSERT INTO merchant_qa (qa_id, merchant_id, user_id, question, answer, answered_by, created_at) VALUES ('QA_CLOUD_SOUND', 'M_CLOUD_LOFT', 'u_ella', 'Did the rear tables hear both microphones during the July sound check?', 'Speech remained clear at the rear tables. Corridor announcements entered the room when the east door was open.', 'Cloud Loft Sales', '2026-07-24T04:05:00Z');
